import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GEMM with scaling and residual add
# output = (input @ weight.T + bias) * scaling_factor + (input @ weight.T + bias)
# Which simplifies to: output = (input @ weight.T + bias) * (scaling_factor + 1.0)

gemm_scale_residual_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 8

__global__ void gemm_scale_residual_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M,
    int N,
    int K,
    float scale_factor
) {
    // Shared memory for tiles
    __shared__ float shared_input[TILE_M][TILE_K];
    __shared__ float shared_weight[TILE_K][TILE_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices
    int row = by * TILE_M + ty;
    int col = bx * TILE_N + tx;

    // Accumulator
    float sum = 0.0f;

    // Iterate over K dimension
    for (int k_tile = 0; k_tile < (K + TILE_K - 1) / TILE_K; ++k_tile) {
        // Load input tile
        int input_k = k_tile * TILE_K + tx;
        if (row < M && input_k < K) {
            shared_input[ty][tx] = input[row * K + input_k];
        } else {
            shared_input[ty][tx] = 0.0f;
        }

        // Load weight tile
        int weight_k = k_tile * TILE_K + ty;
        if (weight_k < K && col < N) {
            shared_weight[ty][tx] = weight[weight_k * N + col];
        } else {
            shared_weight[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            sum += shared_input[ty][k] * shared_weight[k][tx];
        }

        __syncthreads();
    }

    // Apply scaling and write output
    if (row < M && col < N) {
        if (bias != nullptr) {
            output[row * N + col] = (sum + bias[col]) * scale_factor;
        } else {
            output[row * N + col] = sum * scale_factor;
        }
    }
}

torch::Tensor gemm_scale_residual_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float scale_factor
) {
    int M = input.size(0);
    int N = weight.size(0);
    int K = input.size(1);

    auto output = torch::zeros({M, N}, input.options());

    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    dim3 block(TILE_N, TILE_M / TILE_N);
    if (block.y == 0) block.y = 1;

    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    gemm_scale_residual_kernel<<<grid, block>>>(
        input_ptr, weight_ptr, bias_ptr, output_ptr, M, N, K, scale_factor
    );

    return output;
}
"""

gemm_scale_residual = load_inline(
    name="gemm_scale_residual",
    cpp_sources=gemm_scale_residual_cpp_source,
    functions=["gemm_scale_residual_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses matmul, scaling, and residual addition into a single kernel.
    """
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor

        # Initialize weight and bias
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

        # The fused scale is (scaling_factor + 1.0) because:
        # output = matmul(x) * scaling_factor + matmul(x)
        # output = matmul(x) * (scaling_factor + 1.0)
        self.fused_scale = scaling_factor + 1.0

        self.gemm_scale_residual = gemm_scale_residual

    def forward(self, x):
        # Single fused kernel: matmul + scale + residual add
        return self.gemm_scale_residual.gemm_scale_residual_hip(x, self.weight, self.bias, self.fused_scale)

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused InstanceNorm + Divide kernel
instance_norm_divide_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void instance_norm_divide_kernel(
    const float* input, 
    float* output,
    const float* weight, 
    const float* bias,
    const float* running_mean,
    const float* running_var,
    int batch_size, 
    int channels, 
    int height, 
    int width,
    float divide_by,
    float eps,
    bool affine,
    bool track_running_stats
) {
    // Process one channel per thread block
    int c = blockIdx.x;
    int n = blockIdx.y;

    if (n >= batch_size || c >= channels) return;

    int hw = height * width;
    int base_idx = (n * channels + c) * hw;

    // Share memory for reduction
    const int BLOCK_SIZE = 256;
    __shared__ float smem[BLOCK_SIZE];
    __shared__ float smem2[BLOCK_SIZE];

    // Compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        sum += input[base_idx + i];
    }

    smem[threadIdx.x] = sum;
    __syncthreads();

    // Reduce within block
    for (int s = BLOCK_SIZE / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            smem[threadIdx.x] += smem[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = smem[0] / hw;
    __syncthreads();

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        float val = input[base_idx + i] - mean;
        var_sum += val * val;
    }

    smem2[threadIdx.x] = var_sum;
    __syncthreads();

    for (int s = BLOCK_SIZE / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            smem2[threadIdx.x] += smem2[threadIdx.x + s];
        }
        __syncthreads();
    }

    float var = smem2[0] / hw;
    float inv_std = 1.0f / sqrtf(var + eps);

    // Get weight and bias
    float w = affine ? weight[c] : 1.0f;
    float b = affine ? bias[c] : 0.0f;

    // Combine with divide operation
    float combined_weight = w / divide_by;
    float combined_bias = b / divide_by;

    // Normalize and output
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        float normalized = (input[base_idx + i] - mean) * inv_std;
        output[base_idx + i] = combined_weight * normalized + combined_bias;
    }
}

torch::Tensor instance_norm_divide_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float divide_by,
    float eps,
    bool affine,
    bool track_running_stats
) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::zeros_like(input);

    const int block_size = 256;
    dim3 block(block_size);
    dim3 grid(channels, batch_size);

    instance_norm_divide_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        divide_by,
        eps,
        affine,
        track_running_stats
    );

    return output;
}
"""

instance_norm_divide = load_inline(
    name="instance_norm_divide",
    cpp_sources=instance_norm_divide_cpp_source,
    functions=["instance_norm_divide_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model that uses a fused InstanceNorm + Divide kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, divide_by):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

        # Create our own InstanceNorm parameters
        self.instance_norm_divide = instance_norm_divide

        # InstanceNorm parameters
        self.weight = nn.Parameter(torch.ones(out_channels))
        self.bias = nn.Parameter(torch.zeros(out_channels))

        # Running stats (not used in training mode for InstanceNorm)
        self.register_buffer('running_mean', torch.zeros(out_channels))
        self.register_buffer('running_var', torch.ones(out_channels))

        # InstanceNorm hyperparameters
        self.eps = 1e-5
        self.affine = True
        self.track_running_stats = False
        self.divide_by = divide_by

    def forward(self, x):
        x = self.conv(x)

        # Fused InstanceNorm + Divide operation
        x = self.instance_norm_divide.instance_norm_divide_hip(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.divide_by,
            self.eps,
            self.affine,
            self.track_running_stats
        )

        return x

