matmul_pool_sum_scale_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 128

__global__ void matmul_pool_sum_scale_kernel(
    const float* input,  // (batch_size, in_features)
    const float* weight, // (out_features, in_features)
    const float* bias,   // (out_features)
    float* output,       // (batch_size,)
    int batch_size,
    int in_features,
    int out_features,
    float scale_factor
) {
    // Each block processes one sample (one row of the batch)
    int sample_idx = blockIdx.x;
    if (sample_idx >= batch_size) return;

    // Shared memory for accumulating partial sums per output
    // Using BLOCK_SIZE threads, so we need BLOCK_SIZE partial sums
    __shared__ float partial_sums[BLOCK_SIZE];

    // Each thread computes a range of output values
    int out_start = threadIdx.x * ((out_features + BLOCK_SIZE - 1) / BLOCK_SIZE);
    int out_end = min(out_start + ((out_features + BLOCK_SIZE - 1) / BLOCK_SIZE), out_features);

    // Initialize thread's accumulator
    float thread_acc = 0.0f;

    const float* input_ptr = input + sample_idx * in_features;

    // For each output position assigned to this thread
    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        // Compute matmul + maxpool for this output
        // We need to compute values in pairs (2 consecutive outputs for maxpool)
        // But we do it out_idx by out_idx and pool as we go

        // Compute the matmul for this output and its pair
        int pair_out_idx = out_idx + (out_idx % 2 == 0 ? 1 : -1);

        float val1 = 0.0f;
        float val2 = 0.0f;

        // Dot product for two outputs
        const float* w1 = weight + out_idx * in_features;
        const float* w2 = weight + pair_out_idx * in_features;

        for (int k = 0; k < in_features; k += 4) {
            float4 i4, w1_4, w2_4;
            i4 = *reinterpret_cast<const float4*>(input_ptr + k);
            w1_4 = *reinterpret_cast<const float4*>(w1 + k);
            w2_4 = *reinterpret_cast<const float4*>(w2 + k);

            val1 += i4.x * w1_4.x + i4.y * w1_4.y + i4.z * w1_4.z + i4.w * w1_4.w;
            val2 += i4.x * w2_4.x + i4.y * w2_4.y + i4.z * w2_4.z + i4.w * w2_4.w;
        }

        // Add bias
        val1 += bias[out_idx];
        val2 += bias[pair_out_idx];

        // Max pool (but only process if we're at even index)
        if (out_idx % 2 == 0 && pair_out_idx < out_features) {
            float pooled = fmaxf(val1, val2);
            thread_acc += pooled;
        }
    }

    // Store thread's partial sum
    partial_sums[threadIdx.x] = thread_acc;

    // Sync before reduction
    __syncthreads();

    // Reduce within block using parallel reduction
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            partial_sums[threadIdx.x] += partial_sums[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Thread 0 writes the final scaled result
    if (threadIdx.x == 0) {
        output[sample_idx] = partial_sums[0] * scale_factor;
    }
}

torch::Tensor matmul_pool_sum_scale_hip(
    const torch::Tensor input,  // (batch_size, in_features)
    const torch::Tensor weight, // (out_features, in_features)
    const torch::Tensor bias,   // (out_features)
    float scale_factor
) {
    int batch_size = input.size(0);
    int in_features = input.size(1);
    int out_features = weight.size(0);

    // Output is (batch_size,)
    auto output = torch::empty({batch_size}, input.options());

    dim3 grid_dim(batch_size);
    dim3 block_dim(BLOCK_SIZE);

    matmul_pool_sum_scale_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        scale_factor
    );

    return output;
}
"""

matmul_pool_sum_scale = load_inline(
    name="matmul_pool_sum_scale",
    cpp_sources=matmul_pool_sum_scale_cpp_source,
    functions=["matmul_pool_sum_scale_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model that fuses matmul, max pooling, sum, and scaling into a single HIP kernel.
    """
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        # Initialize the Linear layer for compatibility (weight and bias)
        self.matmul = nn.Linear(in_features, out_features)
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor
        self.fused_op = matmul_pool_sum_scale

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size,).
        """
        # Apply fused kernel: matmul + maxpool + sum + scale
        output = self.fused_op.matmul_pool_sum_scale_hip(
            x,
            self.matmul.weight,
            self.matmul.bias,
            self.scale_factor
        )
        return output


