matmul_swish_scale_cpp_source = """
#include <hip/hip_runtime.h>

// Fused kernel: matmul + swish activation + scaling
// Each thread computes one output element (thread-per-row)
// This allows us to apply activation and scaling immediately after computing the dot product
__global__ void matmul_swish_scale_kernel(
    const float* input,      // [batch_size, in_features]
    const float* weight,     // [out_features, in_features]
    const float* bias,       // [out_features] (can be nullptr)
    float* output,           // [batch_size, out_features]
    int batch_size,
    int in_features,
    int out_features,
    float scaling_factor
) {
    // Use 2D thread grid
    int batch_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || out_idx >= out_features) {
        return;
    }

    // Compute dot product for this element
    const float* input_row = input + batch_idx * in_features;
    const float* weight_row = weight + out_idx * in_features;

    float sum = 0.0f;
    for (int i = 0; i < in_features; i++) {
        sum += input_row[i] * weight_row[i];
    }

    // Add bias if available
    if (bias != nullptr) {
        sum += bias[out_idx];
    }

    // Apply Swish activation: x * sigmoid(x)
    // Inline sigmoid: 1 / (1 + exp(-x))
    float sigmoid_val = 1.0f / (1.0f + __expf(-sum));
    float swish_val = sum * sigmoid_val;

    // Apply scaling
    float result = swish_val * scaling_factor;

    // Write output
    output[batch_idx * out_features + out_idx] = result;
}

torch::Tensor matmul_swish_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float scaling_factor
) {
    auto batch_size = input.size(0);
    auto in_features = input.size(1);
    auto out_features = weight.size(0);

    auto output = torch::empty({batch_size, out_features}, input.options());

    // Use 2D thread blocks for better scheduling
    const int block_size_x = 16;  // threads per block for out_features dimension
    const int block_size_y = 16;  // threads per block for batch dimension
    dim3 block_dim(block_size_x, block_size_y);

    // Calculate grid dimensions
    dim3 grid_dim((out_features + block_size_x - 1) / block_size_x,
                  (batch_size + block_size_y - 1) / block_size_y);

    hipLaunchKernelGGL(
        matmul_swish_scale_kernel,
        grid_dim, block_dim, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.numel() > 0 ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        scaling_factor
    );

    return output;
}
"""

matmul_swish_scale = load_inline(
    name="matmul_swish_scale",
    cpp_sources=matmul_swish_scale_cpp_source,
    functions=["matmul_swish_scale_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model with fused matmul + Swish + scaling kernel
    """
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.matmul_swish_scale = matmul_swish_scale

    def forward(self, x):
        # Use fused kernel for matmul + Swish + scale
        x = self.matmul_swish_scale.matmul_swish_scale_hip(
            x,
            self.matmul.weight.t(),  # PyTorch stores weight as [out_features, in_features]
            self.matmul.bias,
            self.scaling_factor
        )
        return x

import os

import torch
