os.environ["CXX"] = "hipcc"

# Fused kernel: Tanh + Scaling + Bias Addition
fused_tanh_scale_bias_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void fused_tanh_scale_bias_kernel(
    const float* input, 
    const float* bias, 
    float* output, 
    int batch_size, 
    int channels, 
    int height, 
    int width,
    float scaling_factor
) {
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;
    int pixel_idx = threadIdx.x + blockIdx.x * blockDim.x;

    int total_pixels = height * width;

    if (batch_idx < batch_size && channel_idx < channels && pixel_idx < total_pixels) {
        int h = pixel_idx / width;
        int w = pixel_idx % width;

        int input_idx = ((batch_idx * channels + channel_idx) * height + h) * width + w;

        // Tanh activation, scaling, and bias addition fused
        float val = tanhf(input[input_idx]);
        val = val * scaling_factor;
