# Fused kernel: Conv2d + BatchNorm + Scaling
# This reduces memory traffic by computing all three operations in a single kernel
# without writing intermediate results to global memory
conv_bn_scale_cpp_source = """
#include <hip/hip_fp16.h>
#include <hip/hip_runtime.h>

__global__ void conv_bn_scale_kernel(
    const float* input,           // [N, IC, H, W]
    const float* weight,          // [OC, IC, KH, KW]
    const float* bias,            // [OC]
    const float* bn_weight,       // [OC] - gamma
    const float* bn_bias,         // [OC] - beta
    const float* running_mean,    // [OC]
    const float* running_var,     // [OC]
    float* output,                // [N, OC, OH, OW]
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int kernel_size,
    int out_height,
    int out_width,
    float scaling_factor,
    float eps) {

    // Each thread computes one output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output = batch_size * out_channels * out_height * out_width;

    if (idx >= total_output) return;

    // Map linear index to (n, oc, oh, ow)
    int n = idx / (out_channels * out_height * out_width);
    int temp = idx % (out_channels * out_height * out_width);
    int oc = temp / (out_height * out_width);
    int oh_ow = temp % (out_height * out_width);
    int oh = oh_ow / out_width;
    int ow = oh_ow % out_width;

    // Compute convolution for this output position
    float sum = 0.0f;
    int half_kernel = kernel_size / 2;

    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
            int ih = oh + kh - half_kernel;
            if (ih < 0 || ih >= in_height) continue;

            for (int kw = 0; kw < kernel_size; kw++) {
                int iw = ow + kw - half_kernel;
                if (iw < 0 || iw >= in_width) continue;

                // Compute indices
                int input_idx = ((n * in_channels + ic) * in_height + ih) * in_width + iw;
                int weight_idx = ((oc * in_channels + ic) * kernel_size + kh) * kernel_size + kw;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    // Add bias
    sum += bias[oc];

    // Apply BatchNorm: output = gamma * (x - mean) / sqrt(var + eps) + beta
    float normalized = (sum - running_mean[oc]) / rsqrtf(running_var[oc] + eps);
    float bn_output = bn_weight[oc] * normalized + bn_bias[oc];

    // Apply scaling
    output[idx] = bn_output * scaling_factor;
}

torch::Tensor conv_bn_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float scaling_factor,
    float eps = 1e-5) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    auto out_channels = weight.size(0);
    auto kernel_size = weight.size(2);

    auto out_height = in_height - kernel_size + 1;
    auto out_width = in_width - kernel_size + 1;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    int total_output = batch_size * out_channels * out_height * out_width;
    const int block_size = 256;
    const int num_blocks = (total_output + block_size - 1) / block_size;

    conv_bn_scale_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_height,
        in_width,
        kernel_size,
        out_height,
        out_width,
        scaling_factor,
        eps
    );

    return output;
}
