    const float* input,      // [batch_size, input_size]
    const float* weight,     // [output_size, input_size]
    const float* bias,       // [output_size]
    float* output,           // [batch_size, output_size]
    int batch_size,
    int input_size,
    int output_size,
    float divisor
) {
