    int batch_idx = blockIdx.x;
    int out_idx = threadIdx.x;

    // Grid-stride loop to handle multiple output elements per thread if needed
    for (int out_col = out_idx; out_col < output_size; out_col += blockDim.x) {
        // Compute dot product for this output element
        float sum = 0.0f;

        // Perform matrix multiplication: input[batch, :] @ weight[out_col, :]
        for (int k = 0; k < input_size; k++) {
            sum += input[batch_idx * input_size + k] * weight[out_col * input_size + k];
        }

        // Add bias
        sum += bias[out_col];

        // Divide by scalar
        sum /= divisor;

        // Apply GELU activation
        sum = gelu(sum);

        // Write to output
        output[batch_idx * output_size + out_col] = sum;
    }
}

