#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_M {TILE_M}
#define TILE_N {TILE_N}
#define TILE_K {TILE_K}

__device__ float gelu(float x) {{
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * x * (1.0f + 0.044715f * x * x)));
}}

__global__ void fused_matmul_avgpool_gelu_scale_max_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    int pool_kernel_size,
    float scale_factor) {{

    // Shared memory for tiles
    __shared__ float tile_input[TILE_M][TILE_K];
    __shared__ float tile_weight[TILE_K][TILE_N];

    // Compute pooled output dimensions
    int pooled_out_features = out_features / pool_kernel_size;

    // Global thread indices for output (M = batch, N = pooled features)
    int global_m = blockIdx.x * TILE_M + threadIdx.y;
    int global_n = blockIdx.y * TILE_N + threadIdx.x;

    // Initialize accumulator for each thread (handles MxN submatrix)
    float accum[TILE_M][TILE_N];
    #pragma unroll
    for (int i = 0; i < TILE_M; i++) {{
        #pragma unroll
        for (int j = 0; j < TILE_N; j++) {{
            accum[i][j] = 0.0f;
        }}
    }}

    // Process all tiles of input (K dimension)
    for (int k_start = 0; k_start < in_features; k_start += TILE_K) {{
        // Load input tile (batch_size x in_features)
        for (int load_m = 0; load_m < TILE_M && (blockIdx.x * TILE_M + load_m) < batch_size; load_m++) {{
            for (int load_k = threadIdx.x; load_k < TILE_K && (k_start + load_k) < in_features; load_k += TILE_N) {{
                int row = blockIdx.x * TILE_M + load_m;
                int col = k_start + load_k;
                tile_input[load_m][load_k] = input[row * in_features + col];
            }}
            for (int load_k = 0; load_k < threadIdx.x && load_k < TILE_K && (k_start + load_k) < in_features; load_k++) {{
                tile_input[load_m][load_k] = 0.0f;
            }}
        }}

        // Load weight tile with pooling in K dimension (in_features x out_features)
        // We accumulate TILE_K columns that map to the same pooled output
        for (int load_k = 0; load_k < TILE_K && (k_start + load_k) < in_features; load_k++) {{
            for (int load_n = threadIdx.y; load_n < TILE_N && (blockIdx.y * TILE_N + load_n) < pooled_out_features; load_n += TILE_M) {{
                // Get the actual column range for this pooled output
                int out_start = (blockIdx.y * TILE_N + load_n) * pool_kernel_size;
                float sum = 0.0f;
                for (int pk = 0; pk < pool_kernel_size && (out_start + pk) < out_features; pk++) {{
                    int col = out_start + pk;
                    sum += weight[(k_start + load_k) * out_features + col];
                }}
                tile_weight[load_k][load_n] = sum;
            }}
        }}

        __syncthreads();

        // Matrix multiplication: compute contributions from this tile
        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {{
            #pragma unroll
            for (int i = 0; i < TILE_M; i++) {{
                if ((blockIdx.x * TILE_M + i) < batch_size && (k_start + k) < in_features) {{
                    float a = tile_input[i][k];
                    #pragma unroll
                    for (int j = 0; j < TILE_N; j++) {{
                        accum[i][j] += a * tile_weight[k][j];
                    }}
                }}
            }}
        }}

        __syncthreads();
    }}

    // Apply pooling (division by pool_kernel_size), GELU, scale
    // Find max across pooled features for each batch element
    float local_max[TILE_M];
    #pragma unroll
    for (int i = 0; i < TILE_M; i++) {{
        local_max[i] = -1e20f; // Initialize to very negative
    }}

    for (int i = 0; i < TILE_M; i++) {{
        int batch_idx = blockIdx.x * TILE_M + i;
        if (batch_idx < batch_size) {{
            for (int j = 0; j < TILE_N; j++) {{
                int feat_idx = blockIdx.y * TILE_N + j;
                if (feat_idx < pooled_out_features) {{
                    // Apply pooling division, activation, scaling
                    float val = (accum[i][j] / (float)pool_kernel_size);
                    val = gelu(val) * scale_factor;
                    // Track max
                    if (val > local_max[i]) {{
                        local_max[i] = val;
                    }}
                }}
            }}
        }}
    }}

    // Warp reduction for max
    #pragma unroll
    for (int i = 0; i < TILE_M; i++) {{
        for (int offset = 8; offset > 0; offset /= 2) {{
            local_max[i] = __builtin_fmaxf(local_max[i], __shfl_down(local_max[i], offset));
        }}
    }}

    // Store results (only lane 0 writes)
    if (threadIdx.x == 0) {{
        for (int i = threadIdx.y; i < TILE_M && (blockIdx.x * TILE_M + i) < batch_size; i += TILE_M) {{
            output[blockIdx.x * TILE_M + i] = local_max[0];
        }}
    }}
}}
