# Fused kernel: Softmax along channel dim + 2x MaxPool3d
# This combines three operations into one to reduce global memory accesses
softmax_pool_fused_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>
#include <float.h>

// Compute max value across channels for exponential computation
__device__ float channel_max(const float* data, int channels, int base_idx) {
    float max_val = -FLT_MAX;
    for (int c = 0; c < channels; c++) {
        float val = data[base_idx + c];
        if (val > max_val) max_val = val;
    }
    return max_val;
}

// Compute sum of exp(x - max) across channels
__device__ float channel_exp_sum(const float* data, int channels, int base_idx, float max_val) {
    float sum = 0.0f;
    for (int c = 0; c < channels; c++) {
        float val = data[base_idx + c];
        sum += expf(val - max_val);
    }
    return sum;
}

// Apply softmax to input data in-place on shared memory
__device__ void apply_softmax(float* data, int channels) {
    // Find max
    float max_val = -FLT_MAX;
    for (int c = 0; c < channels; c++) {
        if (data[c] > max_val) max_val = data[c];
    }

    // Compute sum of exp
    float sum = 0.0f;
    for (int c = 0; c < channels; c++) {
        data[c] = expf(data[c] - max_val);
        sum += data[c];
    }

    // Normalize
    for (int c = 0; c < channels; c++) {
        data[c] /= sum;
    }
}

__global__ void softmax_double_pool_kernel(
    const float* input,  // Shape: [B, C, D1, H1, W1]
    float* output,       // Shape: [B, C, D2, H2, W2] - after 2x2x2 pooling twice
    int batch_size,
    int channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width
) {
    // Output dimensions after two 2x2x2 maxpools
    // Each output position requires reading 4x4x4 = 64 input positions

    int b = blockIdx.z;
    int out_d = blockIdx.y;
    int out_h = blockIdx.x / out_width;
    int out_w = blockIdx.x % out_width;

    if (b >= batch_size || out_d >= out_depth || out_h >= out_height || out_w >= out_width) return;

    // Shared memory to hold pooled data after first pooling
    // Need channels * 2 * 2 * 2 = channels * 8 elements
    extern __shared__ float shared_mem[];
    float* pooled1 = shared_mem;  // After first pool: channels * 2 * 2 * 2

    // Base index for the 4x4x4 region in input
    int base_d = out_d * 4;
    int base_h = out_h * 4;
    int base_w = out_w * 4;

    // Process all channels
    for (int c = 0; c < channels; c++) {
        // First pooling: 2x2x2 regions from 4x4x4 input
        for (int pd = 0; pd < 2; pd++) {
            for (int ph = 0; ph < 2; ph++) {
                for (int pw = 0; pw < 2; pw++) {
                    // Find max in 2x2x2 region
                    float max_val = -FLT_MAX;

                    int start_d = base_d + pd * 2;
                    int start_h = base_h + ph * 2;
                    int start_w = base_w + pw * 2;

                    for (int d = 0; d < 2; d++) {
                        for (int h = 0; h < 2; h++) {
                            for (int w = 0; w < 2; w++) {
                                int id = start_d + d;
                                int ih = start_h + h;
                                int iw = start_w + w;

                                if (id < in_depth && ih < in_height && iw < in_width) {
                                    int in_idx = ((b * channels + c) * in_depth + id) * in_height + ih;
                                    in_idx = in_idx * in_width + iw;
                                    float val = input[in_idx];
                                    if (val > max_val) max_val = val;
                                }
                            }
                        }
                    }

                    // Store in shared memory
                    int pool1_idx = c * 8 + pd * 4 + ph * 2 + pw;
                    pooled1[pool1_idx] = max_val;
                }
            }
        }
    }

    // Sync after first pooling
    __syncthreads();

    // Second pooling: 2x2x2 from pooled1 -> single value per channel
    for (int c = 0; c < channels; c++) {
        float final_max = -FLT_MAX;

        // Find max in 2x2x2 region of pooled1
        for (int i = 0; i < 8; i++) {
            float val = pooled1[c * 8 + i];
            if (val > final_max) final_max = val;
        }

        // Apply softmax to all channels, then find final max
        // Wait, we need to softmax across channels first!
    }

    // We need to softmax across the channel dimension first, then pool
    // Let's redo: softmax on the 8 values from pooled1, then get max
    __syncthreads();

    for (int c = 0; c < channels; c++) {
        // Already have pooled data in pooled1 for this channel
        float max_val = -FLT_MAX;
        for (int i = 0; i < 8; i++) {
            if (pooled1[c * 8 + i] > max_val) max_val = pooled1[c * 8 + i];
        }

        float exp_sum = 0.0f;
        for (int i = 0; i < 8; i++) {
            exp_sum += expf(pooled1[c * 8 + i] - max_val);
        }

        // Softmax normalized max
        float softmax_normalized = 0.0f;
        for (int i = 0; i < 8; i++) {
            float softmax_val = expf(pooled1[c * 8 + i] - max_val) / exp_sum;
            if (softmax_val > softmax_normalized) softmax_normalized = softmax_val;
        }

        // Output
        int out_idx = ((b * channels + c) * out_depth + out_d) * out_height + out_h;
        out_idx = out_idx * out_width + out_w;
        output[out_idx] = softmax_normalized;
    }
}

// Optimized fused kernel: Softmax + 2x MaxPool
__global__ void softmax_double_pool_kernel_optimized(
    const float* input,  // Shape: [B, C, D1, H1, W1]
    float* output,       // Shape: [B, C, D2, H2, W2]
    int batch_size,
    int channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width
) {
    // Grid: [out_height * out_width, out_depth, batch_size]
    int b = blockIdx.z;
    int out_d = blockIdx.y;
    int linear_idx = blockIdx.x;
    int out_h = linear_idx / out_width;
    int out_w = linear_idx % out_width;

    if (b >= batch_size || out_d >= out_depth || out_h >= out_height || out_w >= out_width) return;

    // Shared memory for pooling results
    extern __shared__ float smem[];
    float* pooled1 = smem;  // Size: channels * 8

    // Base input coordinates
    int base_d = out_d * 4;
    int base_h = out_h * 4;
    int base_w = out_w * 4;

    // First pooling: 4x4x4 -> 2x2x2 (8 values per channel)
    #pragma unroll
    for (int c = 0; c < channels; c++) {
        #pragma unroll
        for (int pd = 0; pd < 2; pd++) {
            #pragma unroll
            for (int ph = 0; ph < 2; ph++) {
                #pragma unroll
                for (int pw = 0; pw < 2; pw++) {
                    float max_val = -FLT_MAX;

                    int pool_start_d = base_d + pd * 2;
                    int pool_start_h = base_h + ph * 2;
                    int pool_start_w = base_w + pw * 2;

                    #pragma unroll
                    for (int d = 0; d < 2; d++) {
                        int id = pool_start_d + d;
                        if (id < in_depth) {
                            #pragma unroll
                            for (int h = 0; h < 2; h++) {
                                int ih = pool_start_h + h;
                                if (ih < in_height) {
                                    #pragma unroll
                                    for (int w = 0; w < 2; w++) {
                                        int iw = pool_start_w + w;
                                        if (iw < in_width) {
                                            int in_idx = ((b * channels + c) * in_depth + id) * in_height + ih;
                                            in_idx = in_idx * in_width + iw;
                                            float val = input[in_idx];
                                            if (val > max_val) max_val = val;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    pooled1[c * 8 + pd * 4 + ph * 2 + pw] = max_val;
                }
            }
        }
    }

    __syncthreads();

    // Second pooling: 2x2x2 -> 1, with softmax across channels first
    // Process all channels
    for (int c = 0; c < channels; c++) {
        // Get max of 8 pooled values for softmax stability
        float local_max = pooled1[c * 8];
        #pragma unroll
        for (int i = 1; i < 8; i++) {
            if (pooled1[c * 8 + i] > local_max) local_max = pooled1[c * 8 + i];
        }

        // Compute exp sum
        float exp_sum = 0.0f;
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            exp_sum += expf(pooled1[c * 8 + i] - local_max);
        }

        // Apply softmax and get final max (for second pool)
        float final_max = -FLT_MAX;
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            float softmax_val = expf(pooled1[c * 8 + i] - local_max) / exp_sum;
            if (softmax_val > final_max) final_max = softmax_val;
        }

        // Write output
        int out_idx = ((b * channels + c) * out_depth + out_d) * out_height + out_h;
        out_idx = out_idx * out_width + out_w;
        output[out_idx] = final_max;
    }
}

torch::Tensor softmax_double_pool_hip(torch::Tensor input, int pool_kernel_size) {
    // Input shape: [B, C, D, H, W]
    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    // After first pool
    int mid_depth = (in_depth + pool_kernel_size - 1) / pool_kernel_size;
    int mid_height = (in_height + pool_kernel_size - 1) / pool_kernel_size;
    int mid_width = (in_width + pool_kernel_size - 1) / pool_kernel_size;

    // After second pool (final)
    int out_depth = (mid_depth + pool_kernel_size - 1) / pool_kernel_size;
    int out_height = (mid_height + pool_kernel_size - 1) / pool_kernel_size;
    int out_width = (mid_width + pool_kernel_size - 1) / pool_kernel_size;

    // Create output tensor
    auto output = torch::zeros({batch_size, channels, out_depth, out_height, out_width}, input.dtype());

    // Launch kernel
    const int channels_per_block = 16;
    int shared_size = channels * 8 * sizeof(float);

    dim3 block(1, 1, 1); // Single thread per block for simplicity
    dim3 grid(out_height * out_width, out_depth, batch_size);

    softmax_double_pool_kernel_optimized<<<grid, block, shared_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_depth, in_height, in_width,
        out_depth, out_height, out_width
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        std::cerr << "HIP Error: " << hipGetErrorString(err) << std::endl;
    }

    return output;
}
