matmul_gelu_softmax_source = """
#include <hip/hip_runtime.h>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

__global__ void matmul_gelu_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size, int in_features, int out_features) {

    // Each thread computes one output element
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    // Matrix multiplication computation
    float sum = 0.0f;
    for (int k = 0; k < in_features; k++) {
        sum += x[row * in_features + k] * weight[col * in_features + k];
    }
    sum += bias[col];  // Add bias

    // Apply GELU
    float gelu_val = gelu(sum);

    // Softmax: need to compute across all columns for each row
    // We need to compute max and sum for this row
    // Use shared memory for reduction within the row for the columns we're computing

    extern __shared__ float shared_mem[];
    float* s_max = shared_mem;
    float* s_sum = shared_mem + blockDim.x;

    // Each thread computes its exp value initially (assuming it's max)
    float exp_val = expf(0.0f);  // Will be updated after max computation

    // First, find the row maximum
    // We share across all threads in this row (different columns)
    // Use atomic operations across the row
    __shared__ float row_max_val;
    __shared__ float row_sum_val;

    if (threadIdx.x == 0) {
        row_max_val = -INFINITY;
    }
    __syncthreads();

    // Atomic max on the computed GELU value
    atomicMax(&row_max_val, gelu_val);
    __syncthreads();

    // Now compute exp(gelu_val - row_max) and sum
    float exp_diff = expf(gelu_val - row_max_val);

    if (threadIdx.x == 0) {
        row_sum_val = 0.0f;
    }
    __syncthreads();

    atomicAdd(&row_sum_val, exp_diff);
    __syncthreads();

    // Compute softmax
    out[row * out_features + col] = exp_diff / row_sum_val;
}

torch::Tensor matmul_gelu_softmax(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

