# Fused kernel: computes matmul, scale, and residual add in one pass
# output = (input @ weight.T + bias) * scale + (input @ weight.T + bias)
# output = (input @ weight.T + bias) * (scale + 1.0)

gemm_fused_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 8

__global__ void gemm_fused_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M,
    int N,
    int K,
    float fused_scale
) {
    // Shared memory for tiles
    __shared__ float shared_input[TILE_M][TILE_K];
    __shared__ float shared_weight[TILE_K][TILE_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices
    int row = by * TILE_M + ty;
    int col = bx * TILE_N + tx;

    // Accumulator
    float sum = 0.0f;

    // Iterate over K dimension
    for (int k_tile = 0; k_tile < (K + TILE_K - 1) / TILE_K; ++k_tile) {
        // Load input tile
        int input_k = k_tile * TILE_K + tx;
        if (row < M && input_k < K) {
            shared_input[ty][tx] = input[row * K + input_k];
        } else {
            shared_input[ty][tx] = 0.0f;
        }

        // Load weight tile - transpose handled by indexing
        int weight_k = k_tile * TILE_K + ty;
        if (weight_k < K && col < N) {
            shared_weight[ty][tx] = weight[col * K + weight_k];
        } else {
            shared_weight[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            sum += shared_input[ty][k] * shared_weight[k][tx];
        }

        __syncthreads();
    }

    // Apply fused scaling and write output
    if (row < M && col < N) {
        float bias_val = (bias != nullptr) ? bias[col] : 0.0f;
        output[row * N + col] = (sum + bias_val) * fused_scale;
    }
}

torch::Tensor gemm_fused_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float fused_scale
) {
    int M = input.size(0);
    int N = weight.size(0);
    int K = input.size(1);

    auto output = torch::zeros({M, N}, input.options());

    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    dim3 block(TILE_N, TILE_M / TILE_N);
    if (block.y == 0) block.y = 1;

    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    gemm_fused_kernel<<<grid, block>>>(
        input_ptr, weight_ptr, bias_ptr, output_ptr, M, N, K, fused_scale
    );

    return output;
}
"""

