# Optimized fused kernel: Softmax + 2x MaxPool with proper parallelization
softmax_pool_fused_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>
#include <float.h>

__global__ void softmax_double_pool_optimized(
    const float* input,  // Shape: [B, C, D1, H1, W1]
    float* output,       // Shape: [B, C, D2, H2, W2]
    int batch_size,
    int channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width
) {
    // Global thread ID
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_outputs = batch_size * out_depth * out_height * out_width;

    if (idx >= total_outputs) return;

    // Decode output position
    int idx_flat = idx;
    int w = idx_flat % out_width; idx_flat /= out_width;
    int h = idx_flat % out_height; idx_flat /= out_height;
    int d = idx_flat % out_depth; idx_flat /= out_depth;
    int b = idx_flat;

    // Compute base input coordinates (4x4x4 region maps to 1 output)
    int base_d = d * 4;
    int base_h = h * 4;
    int base_w = w * 4;

    // Shared memory for intermediate pooling results
    extern __shared__ float shared_mem[];
    float* pooled1 = shared_mem;  // Size: channels * 8 (for 2x2x2 pool results)

    // For each channel:
    // 1. First pool: 4x4x4 -> 2x2x2 (8 values)
    // 2. Second pool: 2x2x2 -> 1 (final output)
    for (int c = 0; c < channels; c++) {
        // First pooling
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            int pd = i / 4;    // 0 or 1
            int ph = (i / 2) % 2;  // 0 or 1
            int pw = i % 2;    // 0 or 1

            int start_d = base_d + pd * 2;
            int start_h = base_h + ph * 2;
            int start_w = base_w + pw * 2;

            float max_val = -FLT_MAX;

            #pragma unroll
            for (int ld = 0; ld < 2; ld++) {
                int id = start_d + ld;
                if (id < in_depth) {
                    #pragma unroll
                    for (int lh = 0; lh < 2; lh++) {
                        int ih = start_h + lh;
                        if (ih < in_height) {
                            #pragma unroll
                            for (int lw = 0; lw < 2; lw++) {
                                int iw = start_w + lw;
                                if (iw < in_width) {
                                    int in_idx = ((b * channels + c) * in_depth + id) * in_height + ih;
                                    in_idx = in_idx * in_width + iw;
                                    float val = input[in_idx];
                                    max_val = fmaxf(max_val, val);
                                }
                            }
                        }
                    }
                }
            }

            pooled1[c * 8 + i] = max_val;
        }
    }

    __syncthreads();

    // Second pooling with softmax: process each channel
    for (int c = 0; c < channels; c++) {
        // Find max for numerical stability
        float max_val = -FLT_MAX;
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            max_val = fmaxf(max_val, pooled1[c * 8 + i]);
        }

        // Compute exp sum
        float exp_sum = 0.0f;
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            exp_sum += expf(pooled1[c * 8 + i] - max_val);
        }

        // Apply softmax and find final max
        float final_max = -FLT_MAX;
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            float softmax_val = expf(pooled1[c * 8 + i] - max_val) / exp_sum;
            final_max = fmaxf(final_max, softmax_val);
        }

        // Write output
        int out_idx = ((b * channels + c) * out_depth + d) * out_height + h;
        out_idx = out_idx * out_width + w;
        output[out_idx] = final_max;
    }
}

torch::Tensor softmax_double_pool_hip(torch::Tensor input, int pool_kernel_size) {
    // Input shape: [B, C, D, H, W]
    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    // After first pool
    int mid_depth = (in_depth + pool_kernel_size - 1) / pool_kernel_size;
    int mid_height = (in_height + pool_kernel_size - 1) / pool_kernel_size;
    int mid_width = (in_width + pool_kernel_size - 1) / pool_kernel_size;

    // After second pool (final)
    int out_depth = (mid_depth + pool_kernel_size - 1) / pool_kernel_size;
    int out_height = (mid_height + pool_kernel_size - 1) / pool_kernel_size;
    int out_width = (mid_width + pool_kernel_size - 1) / pool_kernel_size;

    int total_outputs = batch_size * out_depth * out_height * out_width;

    // Create output tensor
    auto output = torch::zeros({batch_size, channels, out_depth, out_height, out_width}, input.dtype());

    // Launch kernel with proper thread configuration
    const int block_size = 256;
    const int num_blocks = (total_outputs + block_size - 1) / block_size;
    int shared_size = channels * 8 * sizeof(float);

    softmax_double_pool_optimized<<<num_blocks, block_size, shared_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_depth, in_height, in_width,
        out_depth, out_height, out_width
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        std::cerr << "HIP Error: " << hipGetErrorString(err) << std::endl;
    }

    return output;
}
"""

