                float val = input[input_idx];
                // Apply fused operations: subtract1, tanh, subtract2
                val = val - subtract1;
                val = tanhf(val);
                val = val - subtract2;

                pool_sum += val;
                count++;
            }
        }
    }

    output[idx] = pool_sum / count;
