import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused kernel: computes matmul, scale, and residual add in one pass
# output = (input @ weight.T + bias) * scale + (input @ weight.T + bias)
# output = (input @ weight.T + bias) * (scale + 1.0)

gemm_fused_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 8

__global__ void gemm_fused_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,  // weight is stored as (out_features, in_features) = (N, K)
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M,
    int N,
    int K,
    float fused_scale
) {
    // Shared memory for tiles
    __shared__ float shared_input[TILE_M][TILE_K];
    __shared__ float shared_weight[TILE_N][TILE_K];  // Transposed storage for weight

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices
    int row = by * TILE_M + ty;
    int col = bx * TILE_N + tx;

    // Accumulator
    float sum = 0.0f;

    // Iterate over K dimension
    for (int k_tile = 0; k_tile < (K + TILE_K - 1) / TILE_K; ++k_tile) {
        // Load input tile
        int input_k = k_tile * TILE_K + tx;
        if (row < M && input_k < K) {
            shared_input[ty][tx] = input[row * K + input_k];
        } else {
            shared_input[ty][tx] = 0.0f;
        }

        // Load weight tile with transpose
        // weight is (N, K), we need (K, N), so weight_T[k][n] = weight[n][k]
        // stored as weight[k*N + n], but weight_ptr[k*N + n] = W[n/k/N???]
        // Actually for weight (N, K) stored row-major: weight[row*N + col] = weight[row*K + col]
        // Wait no, weight is (N, K), so weight[n] = row, weight[k] = col
        // weight[n*K + k] gives element at row n, col k
        // We need transposed version at row k, col n, which is weight[n*K + k]
        // So weight_T[k*N + n] = weight[n*K + k]
        // In the tile: we have col (n) and weight_k (k)
        // So we need weight[n][k] where n=col, k=weight_k
        // That is weight[col * K + weight_k]
        int weight_k = k_tile * TILE_K + ty;  // This is the k dimension
        if (weight_k < K && col < N) {
            shared_weight[tx][ty] = weight[col * K + weight_k];  // weight is (N, K), so we access weight[n][k]
        } else {
            shared_weight[tx][ty] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        // shared_input[ty][k] is A[row][k]
        // shared_weight[tx][k] should be B[k][col] (transposed weight)
        // Wait, shared_weight is arranged as TILE_N x TILE_K
        // shared_weight[tx][ty] has tx in [0, TILE_N), ty in [0, TILE_K)
        // So shared_weight[tx][ty] corresponds to row tx (which is col), col ty (which is k)
        // We loaded it as weight[col * K + weight_k]
        // weight[col*K + weight_k] = weight[n][k] = weight_T[k][n]
        // So shared_weight[tx][ty] = weight_T[ty][tx] = weight[tx][ty]
        // Actually, let me think differently: shared_weight should represent B[k][col]
        // If I store it transposed as shared_weight[col][k], then I need:
        // sum += shared_input[ty][k] * shared_weight[tx][k]
        // where tx=col, k is the inner dimension
        // But we stored shared_weight[tx][ty] where tx=col, ty=k as weight[col*K+k]
        // Wait, that's not transposed, that's the original layout

        // Let me redo this carefully:
        // weight in memory: (N, K) matrix stored row-major
        // weight[n][k] = weight_ptr[n*K + k]
        // We need: for each k, load B[k][col] where B = weight^T
        // B[k][col] = weight[col][k] = weight_ptr[col*K + k]
        // So we load weight_ptr[col*K + k] and store as B[k][col]
        // In our tile: tx goes from 0 to TILE_N-1 (representing col dimension)
        //              ty goes from 0 to TILE_K-1 (representing k dimension)
        // We want shared_weight[k][col] layout
        // shared_weight[ty][tx] = weight[tx][ty]
        // where shared_weight[ty][tx] has row=k, col=col
        // and weight[tx][ty] = weight[col][k]
        // shared_weight[k][col] = weight[col][k] ✓

        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            sum += shared_input[ty][k] * shared_weight[tx][k];
        }

        __syncthreads();
    }

    // Apply fused scaling and write output
    if (row < M && col < N) {
        float bias_val = (bias != nullptr) ? bias[col] : 0.0f;
        output[row * N + col] = (sum + bias_val) * fused_scale;
    }
}

torch::Tensor gemm_fused_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float fused_scale
) {
    int M = input.size(0);
    int N = weight.size(0);
    int K = input.size(1);

    auto output = torch::zeros({M, N}, input.options());

    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    dim3 block(TILE_N, TILE_M / TILE_N);
    if (block.y == 0) block.y = 1;

    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    gemm_fused_kernel<<<grid, block>>>(
        input_ptr, weight_ptr, bias_ptr, output_ptr, M, N, K, fused_scale
    );

    return output;
}
"""

gemm_fused = load_inline(
    name="gemm_fused",
    cpp_sources=gemm_fused_cpp_source,
    functions=["gemm_fused_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses matmul, scaling, and residual addition.
    Preserves the original Linear layer's weights for correctness.
    """
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor

        # Keep the original Linear layer to maintain weight initialization
        self.matmul = nn.Linear(in_features, out_features)

        # The fused scale is (scaling_factor + 1.0) because:
        # x = matmul(x) * scaling_factor + matmul(x)
        # x = matmul(x) * (scaling_factor + 1.0)
        self.fused_scale = scaling_factor + 1.0

        self.gemm_fused = gemm_fused

    def forward(self, x):
        # Use the fused kernel: matmul + fused scale (combining scale + residual add)
        # The kernel handles the weight transpose internally
        return self.gemm_fused.gemm_fused_hip(x, self.matmul.weight, self.matmul.bias, self.fused_scale)

