matmul_gelu_source = """
#include <hip/hip_runtime.h>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

__global__ void matmul_gelu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size, int in_features, int out_features) {

    // Each thread block computes one row of output
    // Use shared memory for the output row
    extern __shared__ float shared_row[];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col_start = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size) return;

    // Process multiple columns per thread
    for (int col = col_start; col < out_features; col += gridDim.x * blockDim.x) {
        // Matrix multiplication computation
        float sum = 0.0f;
        for (int k = 0; k < in_features; k++) {
            sum += x[row * in_features + k] * weight[col * in_features + k];
        }
        sum += bias[col];  // Add bias

        // Apply GELU
        shared_row[threadIdx.y * blockDim.x + threadIdx.x] = gelu(sum);

        // Write to global memory
        out[row * out_features + col] = shared_row[threadIdx.y * blockDim.x + threadIdx.x];
    }
}

torch::Tensor matmul_gelu(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    // Use larger blocks for better utilization
    dim3 block(16, 16);
    int grid_x = (out_features + block.x - 1) / block.x;
    dim3 grid(grid_x, (batch_size + block.y - 1) / block.y);

    int shared_mem_size = block.x * block.y * sizeof(float);

    matmul_gelu_kernel<<<grid, block, shared_mem_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, in_features, out_features
    );

    return out;
}

softmax_source = """
#include <hip/hip_runtime.h>

__global__ void softmax_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int batch_size, int out_features) {

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= batch_size) return;

    // Find max in the row
    float max_val = -INFINITY;
    for (int j = 0; j < out_features; j++) {
        float val = x[row * out_features + j];
        if (val > max_val) {
            max_val = val;
        }
    }

    // Compute sum of exp(x - max)
    float sum = 0.0f;
    for (int j = 0; j < out_features; j++) {
        sum += expf(x[row * out_features + j] - max_val);
    }

    // Compute softmax
    for (int j = 0; j < out_features; j++) {
        out[row * out_features + j] = expf(x[row * out_features + j] - max_val) / sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x, int dim) {
    // Only support dim=1
    int batch_size = x.size(0);
    int out_features = x.size(1);

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, out_features
    );

    return out;
}
"""

