class ModelNew(nn.Module):
    """
    Simple model that performs a matrix multiplication, applies GELU, and then applies Softmax.
    Uses fused matmul+GELU kernel and custom softmax kernel.
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.matmul_gelu = matmul_gelu
        self.softmax_hip = softmax_hip

    def forward(self, x):
        # Compute matmul + gelu
        out = self.matmul_gelu.matmul_gelu(x, self.linear.weight.t(), self.linear.bias)
        # Apply softmax
        out = self.softmax_hip.softmax_hip(out, dim=1)
        return out

