matmul_pool_sum_scale_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 64
#define BLOCK_ROWS 64

__global__ void matmul_pool_sum_scale_kernel(
    const float* input,  // (batch_size, in_features)
    const float* weight, // (out_features, in_features)
    const float* bias,   // (out_features)
    float* output,       // (batch_size,)
    int batch_size,
    int in_features,
    int out_features,
    float scale_factor
) {
    // Each block processes one sample (one row of the batch)
    int sample_idx = blockIdx.x;
    if (sample_idx >= batch_size) return;

    // Shared memory for tiles
    __shared__ float input_tile[TILE_SIZE];
    __shared__ float weight_tile[BLOCK_ROWS][TILE_SIZE];

    // Each thread computes one output (or a few if out_features > BLOCK_ROWS)
    int out_idx = threadIdx.x;

    // Accumulator for matmul result
    float matmul_result = 0.0f;

    const float* input_row = input + sample_idx * in_features;
    const float* weight_row = weight + out_idx * in_features;

    // Tiled matrix multiplication
    for (int tile_start = 0; tile_start < in_features; tile_start += TILE_SIZE) {
        int tile_end = min(tile_start + TILE_SIZE, in_features);
        int tile_size = tile_end - tile_start;

        // Load input tile coalesced (each thread loads one element)
        int global_in_idx = tile_start + threadIdx.x;
        if (threadIdx.x < tile_size) {
            input_tile[threadIdx.x] = input_row[global_in_idx];
        }

        // Load weight tile (each thread loads one row of TILE_SIZE elements)
        if (out_idx < out_features) {
            for (int k = 0; k < tile_size; k++) {
                weight_tile[threadIdx.x][k] = weight_row[tile_start + k];
            }
        }

        __syncthreads();

        // Compute partial dot product
        if (out_idx < out_features) {
            float sum = 0.0f;
            #pragma unroll
            for (int k = 0; k < TILE_SIZE; k += 4) {
                if (k + 3 < tile_size) {
                    float4 i4, w4;
                    i4 = *reinterpret_cast<float4*>(input_tile + k);
                    w4 = *reinterpret_cast<float4*>(&weight_tile[threadIdx.x][k]);
                    sum += i4.x * w4.x + i4.y * w4.y + i4.z * w4.z + i4.w * w4.w;
                } else {
                    // Handle remaining elements
                    for (int kk = k; kk < tile_size; kk++) {
                        sum += input_tile[kk] * weight_tile[threadIdx.x][kk];
                    }
                }
            }
            matmul_result += sum;
        }

        __syncthreads();
    }

    // Add bias and get pair index for max pooling
    int paired_out_idx = (out_idx % 2 == 0) ? out_idx + 1 : out_idx - 1;

    // Get paired thread's result via shared memory
    __shared__ float output_values[BLOCK_ROWS];

    if (out_idx < out_features) {
        matmul_result += bias[out_idx];
        output_values[out_idx] = matmul_result;
    }

    __syncthreads();

    // Max pool and accumulate per thread
    float thread_sum = 0.0f;
    if (out_idx < out_features && out_idx % 2 == 0 && out_idx + 1 < out_features) {
        float pooled = fmaxf(output_values[out_idx], output_values[out_idx + 1]);
        thread_sum = pooled;
    }

    // Parallel reduction within block
    __shared__ float partial_sums[BLOCK_ROWS];
    partial_sums[threadIdx.x] = thread_sum;

    __syncthreads();

    for (int s = BLOCK_ROWS / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            partial_sums[threadIdx.x] += partial_sums[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Thread 0 writes the final scaled result
    if (threadIdx.x == 0) {
        output[sample_idx] = partial_sums[0] * scale_factor;
    }
}

torch::Tensor matmul_pool_sum_scale_hip(
    const torch::Tensor input,  // (batch_size, in_features)
    const torch::Tensor weight, // (out_features, in_features)
    const torch::Tensor bias,   // (out_features)
    float scale_factor
