# Fused Matmul + Dropout + Softmax kernel with correct indexing
fused_kernel_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ x,           // (batch_size, in_features)
    const float* __restrict__ weight,      // (out_features, in_features) - PyTorch Linear format
    const float* __restrict__ bias,         // (out_features)
    float* __restrict__ output,            // (batch_size, out_features)
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    float scale,
    bool training
) {
    int out_row = blockIdx.y * blockDim.y + threadIdx.y;
    int out_col = blockIdx.x * blockDim.x + threadIdx.x;

    if (out_row >= batch_size || out_col >= out_features) return;

    // Compute matmul: output[row, col] = sum(x[row, k] * weight[col, k])
    float sum = 0.0f;

    // Each thread computes its own matrix multiplication
    for (int k = 0; k < in_features; ++k) {
        // Linear layer: weight is (out_features, in_features), so weight[out_col, k]
        sum += x[out_row * in_features + k] * weight[out_col * in_features + k];
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[out_col];
    }

    // Apply dropout (only during training)
    if (training) {
        // Simple hash-based PRNG for reproducibility
        unsigned int idx = (unsigned int)(out_row * out_features + out_col);
        unsigned int hash = idx * 0x9e3779b9;
        hash ^= hash >> 16;
        hash *= 0x85ebca6b;
        hash ^= hash >> 13;
        hash *= 0xc2b2ae35;
        hash ^= hash >> 16;
        float rand_val = (float)(hash & 0xFFFFFF) / (float)0x1000000;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum = sum * scale;  // scale = 1.0 / (1.0 - dropout_p)
        }
    }

    output[out_row * out_features + out_col] = sum;
}

__global__ void softmax_kernel(
    float* __restrict__ x,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    __shared__ float s_max[1024];
    __shared__ float s_sum[1024];
    int tid = threadIdx.x + threadIdx.y * blockDim.x;
    int bid = blockIdx.y;

    int idx = row * out_features + col;
    float val = x[idx];

    // Find max per row using parallel reduction
    s_max[tid] = val;
    __syncthreads();

    for (int stride = blockDim.x * blockDim.y / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_max[tid] = fmaxf(s_max[tid], s_max[tid + stride]);
        }
        __syncthreads();
    }

    float max_val = s_max[0];
    __syncthreads();

    // Compute sum of exp
    val = expf(fmaxf(val - max_val, -50.0f));  // Stable softmax
    x[idx] = val;

    s_sum[tid] = val;
    __syncthreads();

    for (int stride = blockDim.x * blockDim.y / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] = s_sum[tid] + s_sum[tid + stride];
        }
        __syncthreads();
    }

    float sum_exp = s_sum[0];
    __syncthreads();

    // Normalize
    x[idx] = val / fmaxf(sum_exp, 1e-10f);
}

torch::Tensor fused_matmul_dropout_softmax_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float dropout_p,
    bool training
) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());
    float scale = 1.0f / (1.0f - dropout_p + 1e-6f);

    // Launch matmul+dropout kernel
    int block_size = 256;
    dim3 blockDim(32, 8);  // 32x8 = 256 threads
    dim3 gridDim((out_features + 31) / 32, (batch_size + 7) / 8);

    fused_matmul_dropout_softmax_kernel<<<gridDim, blockDim>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        dropout_p,
        scale,
        training
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        // Fallback to simpler block configuration
        dim3 blockDim2(16, 16);
        dim3 gridDim2((out_features + 15) / 16, (batch_size + 15) / 16);
        fused_matmul_dropout_softmax_kernel<<<gridDim2, blockDim2>>>(
