            output.data_ptr<float>(),
            batch_size,
            in_features,
            out_features,
            dropout_p,
            scale,
            training
        );
    }

    // Launch softmax kernel
    int s_block_x = 32;
    int s_block_y = 32;
    dim3 s_thread(s_block_x, s_block_y);
    dim3 s_grid((out_features + s_block_x - 1) / s_block_x, (batch_size + s_block_y - 1) / s_block_y);

