matmul_swish_scale_cpp_source = """
#include <hip/hip_runtime.h>

// Tile sizes for shared memory tiling
#define TILE_SIZE_M 8
#define TILE_SIZE_N 32
#define TILE_SIZE_K 8

// Fused kernel: matmul + swish activation + scaling with tiling
__global__ void matmul_swish_scale_tiled_kernel(
    const float* input,      // [batch_size, in_features]
    const float* weight,     // [in_features, out_features]  (column-major as returned by weight.t())
    const float* bias,       // [out_features] (can be nullptr)
    float* output,           // [batch_size, out_features]
    int batch_size,
    int in_features,
    int out_features,
    float scaling_factor
) {
    // Block computes TILE_SIZE_M x TILE_SIZE_N tile of output
    int batch_start = blockIdx.y * TILE_SIZE_M;
    int out_start = blockIdx.x * TILE_SIZE_N;

    // Each thread computes one output element in the tile
    int batch_idx = batch_start + threadIdx.y;
    int out_idx = out_start + threadIdx.x;

    // Shared memory tiles
    __shared__ float input_tile[TILE_SIZE_M][TILE_SIZE_K];
    __shared__ float weight_tile[TILE_SIZE_K][TILE_SIZE_N];

    // Accumulator
    float sum = 0.0f;

    // Loop over K dimension in tiles
    for (int k_tile = 0; k_tile < in_features; k_tile += TILE_SIZE_K) {
        // Load input tile
        // input is [batch_size, in_features], row-major
        // For tile: row = batch_idx, col = k_tile + threadIdx.x (K dimension)

        int k_idx = k_tile + threadIdx.x;

        if (threadIdx.y < TILE_SIZE_M) {  // Only load the first TILE_SIZE_M threads in y dimension
            int load_batch_idx = batch_start + threadIdx.y;
            if (load_batch_idx < batch_size && k_idx < in_features) {
                input_tile[threadIdx.y][threadIdx.x] = input[load_batch_idx * in_features + k_idx];
            } else {
                input_tile[threadIdx.y][threadIdx.x] = 0.0f;
            }
        }

        // Load weight tile
        // weight (passed to kernel) is actually the transposed version
        // Original weight is [out_features, in_features] from PyTorch
        // We pass self.matmul.weight which is [out_features, in_features], NOT transposed
        // For GEMM: output[batch, out] = sum_k input[batch, k] * weight[out, k]

        if (threadIdx.x < TILE_SIZE_N) {  // Only load first TILE_SIZE_N threads in x dimension
            int load_out_idx = out_start + threadIdx.x;
            if (k_idx < in_features && load_out_idx < out_features) {
                // weight is [out_features, in_features], row-major
                // Access weight[out_idx, k_idx]
                weight_tile[threadIdx.x][threadIdx.y] = weight[load_out_idx * in_features + k_idx];
            } else {
                weight_tile[threadIdx.x][threadIdx.y] = 0.0f;
            }
        }

        __syncthreads();

        // Each thread computes one element in the TILE_SIZE_M x TILE_SIZE_N output tile
        if (threadIdx.x < TILE_SIZE_N && threadIdx.y < TILE_SIZE_M) {
            #pragma unroll
            for (int k = 0; k < TILE_SIZE_K; k++) {
                // input_tile[row][k] * weight_tile[k][col]
                sum += input_tile[threadIdx.y][k] * weight_tile[k][threadIdx.x];
            }
        }

        __syncthreads();
    }

    // Apply activation and scaling if in bounds
    if (batch_idx < batch_size && out_idx < out_features) {
        // Add bias if available
        if (bias != nullptr) {
            sum += bias[out_idx];
        }

        // Apply Swish activation: x * sigmoid(x)
        float sigmoid_val = 1.0f / (1.0f + __expf(-sum));
        float swish_val = sum * sigmoid_val;

        // Apply scaling
        float result = swish_val * scaling_factor;

        // Write output
        output[batch_idx * out_features + out_idx] = result;
    }
