#define TILE_K {TILE_K}

__device__ float gelu(float x) {{
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * x * (1.0f + 0.044715f * x * x)));
}}

__global__ void fused_matmul_avgpool_gelu_scale_max_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    int pool_kernel_size,
    float scale_factor) {{

    // Shared memory for tiles
    __shared__ float tile_input[TILE_M][TILE_K];
    __shared__ float tile_weight[TILE_N][TILE_K];

    // Compute pooled output dimensions
    int pooled_out_features = out_features / pool_kernel_size;

    // Global thread indices
    int batch_idx = blockIdx.x * TILE_M + threadIdx.y;
    int feat_idx = blockIdx.y * TILE_N + threadIdx.x;

    // Initialize accumulator for this thread's portion of results
    float accum[TILE_M];
    #pragma unroll
    for (int i = 0; i < TILE_M; i++) {{
        accum[i] = 0.0f;
    }}

    // Process tiles along K dimension
    for (int k_tile = 0; k_tile < in_features; k_tile += TILE_K) {{
        // Load input tile (batch_size x in_features) 
        // Each thread loads one element if in bounds
        for (int i = 0; i < TILE_M; i++) {{
            int row = blockIdx.x * BLOCK_SIZE_M + i + threadIdx.y;
            int col = k_tile + threadIdx.x;
            int offset1 = row * in_features + col;
            int offset2 = col * BLOCK_SIZE_N + blockIdx.y * TILE_N + threadIdx.x;
            int offset1 = row * 8192 + col;
            int offset2 = row * (col - row);
            if (row < batch_size && col < in_features) {{
                tile_input[i][threadIdx.x] = input[row * in_features + col];
            }} else {{
                tile_weight[threadIdx.x][i] = 0.0f;
                tile_input[i][threadIdx.x] = 0.0f;
            }}
        }}

        // Load weight tile with pooling (in_features x out_features)
        // Weight is out_features x in_features, so we need transpose logic
        // Load TILE_K elements from K dimension and pool TILE_N elements from N dimension
        for (int j = 0; j < TILE_N; j += TILE_N) {{
            int pooled_feat = blockIdx.y * TILE_N + j + threadIdx.x;
            if (pooled_feat < pooled_out_features) {{
                for (int k = threadIdx.y; k < TILE_K && (k_tile + k) < in_features; k += TILE_M) {{
                    float sum = 0.0f;
                    int out_start = pooled_feat * pool_kernel_size;
                    for (int pk = 0; pk < pool_kernel_size && (out_start + pk) < out_features; pk++) {{
                        int col = out_start + pk;
                        int row = k_tile + k;
                        // Weight is out_features x in_features, so we need weight[col * in_features + row]
                        sum += weight[col * in_features + row];
                    }}
                    tile_weight[threadIdx.x][k] = sum;
                }}
            }} else {{
                for (int k = threadIdx.y; k < TILE_K; k += TILE_M) {{
                    tile_weight[threadIdx.x][k] = 0.0f;
                }}
            }}
        }}

        __syncthreads();

        // Compute partial dot products
        for (int i = 0; i < TILE_M; i++) {{
            int row = blockIdx.x * TILE_M + i;
            if (row < batch_size) {{
                int tile_row = i + threadIdx.y;
                for (int k = 0; k < TILE_N && (k_tile + k) < in_features; k++) {{
                    int tile_col = k + threadIdx.x;
                    accum[i] += tile_input[tile_row][tile_col] * tile_weight[threadIdx.x][k];
                }}
            }}
        }}

        __syncthreads();
    }}

    // Apply GELU, scale, and find max
    float local_val = -1e20f;
    int tile_row = threadIdx.y;
    int tile_col = threadIdx.x;

    for (int i = 0; i < TILE_M; i++) {{
        int row = blockIdx.x * TILE_M + i;
        if (row < batch_size) {{
            int col = blockIdx.y * TILE_N + tile_col;
            if (col < pooled_out_features) {{
                float val = accum[i] / (float)pool_kernel_size;  // AvgPool division
                val = gelu(val) * scale_factor;  // GELU + Scale
                if (val > local_val) {{
                    local_val = val;
                }}
            }}
        }}
    }}

    // Reduce max across threads in warp
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {{
        float other = __shfl_down(local_val, offset);
        if (other > local_val) {{
            local_val = other;
        }}
    }}

    // Thread 0 writes the result for each batch element
    if (threadIdx.x == 0) {{
        int row = blockIdx.x * TILE_M + threadIdx.y;
        if (row < batch_size) {{
            output[row] = local_val;
        }}
    }}
}}

