#include <hip/hip_runtime.h>

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ bias,
    float* __restrict__ C,
    int batch_size,
    int M,
    int N,
    int K,
    bool use_bias
) {
    int row = blockIdx.x * blockDim.y + threadIdx.y;  // batch dimension
    int col = blockIdx.y * blockDim.x + threadIdx.x;  // output feature dimension

    if (row < M && col < N) {
        float sum = 0.0f;

        // Matrix multiplication
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[col * K + k];
        }

        // Swish activation
        float sigmoid_x = 1.0f / (1.0f + expf(-sum));
        float swish_out = sigmoid_x * sum;

        // Bias addition
        if (use_bias) {
            swish_out += bias[col];
        }

        C[row * N + col] = swish_out;
    }
}

