    const int blockDim_y = 16;

    dim3 blockDim(blockDim_x, blockDim_y);
    dim3 gridDim((N + blockDim_x - 1) / blockDim_x, (M + blockDim_y - 1) / blockDim_y);

    bool use_bias = bias.numel() > 0;

    fused_matmul_swish_bias_kernel<<<gridDim, blockDim>>>(
