# Define tile sizes
TILE_M = 32
TILE_N = 128
TILE_K = 32

fused_kernel_cpp_source = f"""
#include <hip/hip_runtime.h>

#define TILE_M {TILE_M}
#define TILE_N {TILE_N}
#define TILE_K {TILE_K}

__device__ float gelu(float x) {{
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * x * (1.0f + 0.044715f * x * x)));
}}

__global__ void fused_matmul_avgpool_gelu_scale_max_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    int pool_kernel_size,
    float scale_factor) {{

    // Shared memory for tiles
    __shared__ float tile_input[TILE_M][TILE_K];
    __shared__ float tile_weight[TILE_N][TILE_K];

    // Compute pooled output dimensions
    int pooled_out_features = out_features / pool_kernel_size;

    // Global thread indices
    int batch_block = blockIdx.x;
    int feat_block = blockIdx.y;

    // Initialize accumulator for each row this thread handles
    float accum[TILE_M];
    #pragma unroll
    for (int i = 0; i < TILE_M; i++) {{
        accum[i] = 0.0f;
    }}

    // Process tiles along K dimension
    for (int k_tile = 0; k_tile < in_features; k_tile += TILE_K) {{
        // Load input tile (batch_size x in_features)
        for (int i = 0; i < TILE_M; i++) {{
            int row = batch_block * TILE_M + i;
            int col = k_tile + threadIdx.x;
            if (row < batch_size && col < in_features) {{
                tile_input[i][threadIdx.x] = input[row * in_features + col];
            }} else {{
                tile_input[i][threadIdx.x] = 0.0f;
            }}
        }}

        // Load weight tile with pooling
        // Weight is out_features x in_features, need to load chunks of pool_kernel_size columns
        // and average them for pooled output
        for (int j = threadIdx.x; j < TILE_N; j++) {{
            int pooled_feat = feat_block * TILE_N + j;
            if (pooled_feat < pooled_out_features) {{
                for (int k = threadIdx.y; k < TILE_K && (k_tile + k) < in_features; k += TILE_M) {{
                    float sum = 0.0f;
                    int out_start = pooled_feat * pool_kernel_size;
                    for (int pk = 0; pk < pool_kernel_size && (out_start + pk) < out_features; pk++) {{
                        int col = out_start + pk;  // pooled output column
                        int row = k_tile + k;      // input feature
                        sum += weight[col * in_features + row];
                    }}
                    tile_weight[j][k] = sum;
                }}
            }} else {{
                for (int k = threadIdx.y; k < TILE_K; k += TILE_M) {{
                    tile_weight[j][k] = 0.0f;
                }}
            }}
        }}

        __syncthreads();

        // Compute partial dot products
        for (int i = 0; i < TILE_M; i++) {{
            int row = batch_block * TILE_M + i;
            if (row < batch_size) {{
                for (int k = 0; k < TILE_K && (k_tile + k) < in_features; k++) {{
                    float a = tile_input[i][k];
                    for (int j = 0; j < TILE_N; j++) {{
                        accum[i] += a * tile_weight[j][k];
                    }}
                }}
            }}
        }}

        __syncthreads();
    }}

    // Apply GELU, scale, and find max
    float local_val = -1e20f;

    for (int i = 0; i < TILE_M; i++) {{
        int row = batch_block * TILE_M + i;
        if (row < batch_size) {{
            for (int j = threadIdx.x; j < TILE_N; j++) {{
                int col = feat_block * TILE_N + j;
                if (col < pooled_out_features) {{
                    float val = accum[i] / (float)pool_kernel_size;  // AvgPool division
                    val = gelu(val) * scale_factor;  // GELU + Scale
                    if (val > local_val) {{
                        local_val = val;
                    }}
                }}
            }}
        }}
    }}

    // Reduce max across threads in warp
    for (int offset = 16; offset > 0; offset /= 2) {{
        float other = __shfl_down(local_val, offset);
        if (other > local_val) {{
            local_val = other;
        }}
    }}

    // Thread 0 writes the result for each row
    if (threadIdx.x == 0) {{
        for (int i = threadIdx.y; i < TILE_M; i++) {{
            int row = batch_block * TILE_M + i;
            if (row < batch_size) {{
                output[row] = local_val;
            }}
        }}
    }}
}}

torch::Tensor fused_matmul_avgpool_gelu_scale_max_hip(
    torch::Tensor input,
    torch::Tensor weight,
    float scale_factor,
    int pool_kernel_size) {{

    int batch_size = input.size(0);
    int in_features = input.size(1);
    int out_features = weight.size(0);
    int pooled_out_features = out_features / pool_kernel_size;

    auto output = torch::empty({{batch_size}}, input.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((batch_size + TILE_M - 1) / TILE_M, (pooled_out_features + TILE_N - 1) / TILE_N);

    fused_matmul_avgpool_gelu_scale_max_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        pool_kernel_size,
