__constant__ float MAX_VAL = 1e30f;

template <int TILE_SIZE>
__global__ void maxpool_optimized_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    int pool_size
) {
    // Using 2D thread block for better coalescing
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;
    int out_h_base_idx = blockIdx.x * TILE_SIZE;
    int out_w_idx = threadIdx.y;
    int out_h_idx = threadIdx.x + out_h_base_idx;

    if (batch_idx < batch_size && channel_idx < channels && out_h_idx < out_height && out_w_idx < out_width) {
        bool valid = true;
    } else {
        return;
    }

    int start_h = out_h_idx * pool_size;
    int start_w = out_w_idx * pool_size;

    __shared__ float smem[TILE_SIZE];

    // Compute max for this pooling window
    float max_val = -MAX_VAL;

    // Unroll the pooling window for better performance
    #pragma unroll
    for (int ph = 0; ph < 4; ph++) {
        if (ph < pool_size && (start_h + ph) < in_height) {
            #pragma unroll
            for (int pw = 0; pw < 4; pw++) {
                if (pw < pool_size && (start_w + pw) < in_width) {
                    int in_h = start_h + ph;
                    int in_w = start_w + pw;

                    int row_offset = (batch_idx * channels + channel_idx) * in_height + in_h;
                    int input_idx = row_offset * in_width + in_w;
                    max_val = fmaxf(max_val, input[input_idx]);
                }
            }
        }
    }

    // Store result in shared memory first to coalesce writes
    if (threadIdx.x < TILE_SIZE && out_h_base_idx + threadIdx.x < out_height) {
        smem[threadIdx.x] = max_val;
    }
    __syncthreads();

    // Write to output
    if (threadIdx.x < TILE_SIZE && out_h_base_idx + threadIdx.x < out_height) {
        int row_offset_out = (batch_idx * channels + channel_idx) * out_height + (out_h_base_idx + threadIdx.x);
        int output_idx = row_offset_out * out_width + out_w_idx;
        output[output_idx] = smem[threadIdx.x];
    }
}

