fused_matmul_swish_bias_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ bias_ptr,
    float* __restrict__ C,
    int M,
    int N,
    int K,
    bool use_bias
) {
    int row = blockIdx.x * blockDim.y + threadIdx.y;
    int col = blockIdx.y * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;

        // Matrix multiplication: compute C[row,col] = sum_k A[row,k] * B[col,k]
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[col * K + k];
        }

        // Swish activation
        float sigmoid_x = 1.0f / (1.0f + expf(-sum));
        float swish_out = sigmoid_x * sum;

        // Bias addition
        if (use_bias && bias_ptr != nullptr) {
            swish_out += bias_ptr[col];
        }

        C[row * N + col] = swish_out;
    }
}

torch::Tensor fused_matmul_swish_bias_hip(torch::Tensor A, torch::Tensor B, c10::optional<torch::Tensor> bias_opt) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto C = torch::empty({M, N}, A.options());

    const int blockDim_x = 16;
    const int blockDim_y = 16;

    dim3 blockDim(blockDim_x, blockDim_y);
    dim3 gridDim((N + blockDim_x - 1) / blockDim_x, (M + blockDim_y - 1) / blockDim_y);

    bool use_bias = bias_opt.has_value() && bias_opt.value().numel() > 0;
    const float* bias_ptr = use_bias ? bias_opt.value().data_ptr<float>() : nullptr;

    fused_matmul_swish_bias_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        bias_ptr,
        C.data_ptr<float>(),
        M,
        N,
        K,
        use_bias
    );

    return C;
}
"""

