instance_norm_divide_cpp_source = """
#include <hip/hip_runtime.h>

// Warp-level reduction
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void instance_norm_divide_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output,
    const float* __restrict__ weight, 
    const float* __restrict__ bias,
    int batch_size, 
    int channels, 
    int height, 
    int width,
    float divide_by,
    float eps
) {
    int n = blockIdx.y;  // batch
    int c = blockIdx.x;  // channel

    if (n >= batch_size || c >= channels) return;

    int hw = height * width;
    int base_idx = (n * channels + c) * hw;
    const float* __restrict__ in_ptr = input + base_idx;
    float* __restrict__ out_ptr = output + base_idx;

    const int BLOCK_SIZE = 256;
    const int WAVE_SIZE = 64;

    // === Compute mean ===
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        sum += in_ptr[i];
    }

    // Warp reduction first
    int lane = threadIdx.x % WAVE_SIZE;
    int warp_id = threadIdx.x / WAVE_SIZE;

    __shared__ float warp_smem[4];  // 4 warps per block

    sum = warp_reduce_sum(sum);

    if (lane == 0) {
        warp_smem[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction
    sum = (threadIdx.x < 4) ? warp_smem[threadIdx.x] : 0.0f;
    if (warp_id == 0) {
        sum = warp_reduce_sum(sum);
    }

    float mean = (lane == 0 && warp_id == 0) ? sum / (float)hw : 0.0f;
    mean = __shfl(mean, 0);  // Broadcast mean to all threads

    __syncthreads();

    // === Compute variance ===
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        float diff = in_ptr[i] - mean;
        var_sum += diff * diff;
    }

    // Warp reduction
    var_sum = warp_reduce_sum(var_sum);

    if (lane == 0) {
        warp_smem[warp_id] = var_sum;
    }
    __syncthreads();

    var_sum = (threadIdx.x < 4) ? warp_smem[threadIdx.x] : 0.0f;
    if (warp_id == 0) {
        var_sum = warp_reduce_sum(var_sum);
    }

    float inv_std = (lane == 0 && warp_id == 0) ? 
        1.0f / sqrtf(fmaxf(var_sum / (float)hw, eps)) : 0.0f;
    inv_std = __shfl(inv_std, 0);

    __syncthreads();

    // === Get affine parameters and combine with divide ===
    float w = weight[c];
    float b = bias[c];

    // Combine multiplication/division: (weight * normalized) / divide_by
    float scale = w / divide_by;
    float shift = b / divide_by;

    // === Normalize and output ===
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        out_ptr[i] = scale * (in_ptr[i] - mean) * inv_std + shift;
    }
}

torch::Tensor instance_norm_divide_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float divide_by,
    float eps
) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::zeros_like(input);

    const int block_size = 256;
    dim3 block(block_size);
