matmul_gelu_source = """
#include <hip/hip_runtime.h>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

#define TILE_SIZE 16
#define BLOCK_SIZE 256

// For large matrices, use optimized matmul without shared memory tiling
// but with coalesced access patterns
__global__ void matmul_gelu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size, int in_features, int out_features) {

    // Each thread computes one output element
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    // Read the entire row of x into register if possible
    const float* x_row = x + row * in_features;

    float sum = 0.0f;

    // Unroll the loop for better performance
    for (int k = 0; k < in_features; k++) {
        sum += x_row[k] * weight[col * in_features + k];
    }

    sum += bias[col];

    // Apply GELU
    out[row * out_features + col] = gelu(sum);
}

torch::Tensor matmul_gelu(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    // Optimize for large matrices - use 32x32 blocks for better occupancy
    dim3 block(32, 8);
    dim3 grid((out_features + block.x - 1) / block.x, (batch_size + block.y - 1) / block.y);

    matmul_gelu_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, in_features, out_features
    );

    return out;
}

// Optimized softmax kernel with shared memory for max finding
__global__ void softmax_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int batch_size, int out_features) {

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= batch_size) return;

    const float* row_ptr = x + row * out_features;
    float* out_ptr = out + row * out_features;

    // Phase 1: Find maximum in the row
    float max_val = -INFINITY;

    // Use unrolling and vectorized loads if possible
    for (int j = 0; j < out_features; j++) {
        float val = row_ptr[j];
        if (val > max_val) {
            max_val = val;
        }
    }

    // Phase 2: Compute sum of exp(x - max)
    float sum = 0.0f;
    for (int j = 0; j < out_features; j++) {
        sum += expf(row_ptr[j] - max_val);
    }

    // Phase 3: Compute softmax
