matmul_gelu_softmax_source = """
#include <hip/hip_runtime.h>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

// Tiled matrix multiplication with GELU fusion
#define TILE_SIZE 32

__global__ void matmul_gelu_kernel(
    const float* __restrict__ A,  // [batch_size, in_features]
    const float* __restrict__ B,  // [out_features, in_features]
    const float* __restrict__ bias,
    float* __restrict__ C,
    int batch_size, int in_features, int out_features) {

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    // Shared memory for tiling
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;

    // Iterate over tiles of the input matrix
    int num_tiles = (in_features + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < num_tiles; t++) {
        // Load tile of A (input row)
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (a_col < in_features) {
            As[threadIdx.y][threadIdx.x] = A[row * in_features + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B (weights)
        int b_row = blockIdx.x * blockDim.x + threadIdx.y;
        int b_col = t * TILE_SIZE + threadIdx.x;
        if (b_row < out_features && b_col < in_features) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * in_features + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[threadIdx.x][k];
        }

        __syncthreads();
    }

    // Add bias and apply GELU
    int c_row = blockIdx.y * blockDim.y + threadIdx.y;
    int c_col = blockIdx.x * blockDim.x + threadIdx.x;

    if (c_row < batch_size && c_col < out_features) {
        C[c_row * out_features + c_col] = gelu(sum + bias[c_col]);
    }
}

torch::Tensor matmul_gelu(torch::Tensor A, torch::Tensor B, torch::Tensor bias) {
    auto batch_size = A.size(0);
    auto in_features = A.size(1);
    auto out_features = B.size(0);

    auto C = torch::zeros({batch_size, out_features}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((out_features + TILE_SIZE - 1) / TILE_SIZE, (batch_size + TILE_SIZE - 1) / TILE_SIZE);

    matmul_gelu_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        bias.data_ptr<float>(),
        C.data_ptr<float>(),
        batch_size, in_features, out_features
    );

    return C;
}

__global__ void softmax_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int batch_size, int out_features) {

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= batch_size) return;

    const float* row_ptr = x + row * out_features;
    float* out_ptr = out + row * out_features;

    // Find maximum
    float max_val = -INFINITY;
    for (int j = 0; j < out_features; j++) {
        float val = row_ptr[j];
        max_val = fmaxf(max_val, val);
    }

    // Compute sum of exp
    float sum = 0.0f;
    for (int j = 0; j < out_features; j++) {
        sum += expf(row_ptr[j] - max_val);
    }

    // Compute softmax
    float inv_sum = 1.0f / (sum + 1e-8f);
    for (int j = 0; j < out_features; j++) {
        out_ptr[j] = expf(row_ptr[j] - max_val) * inv_sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    int batch_size = x.size(0);
    int out_features = x.size(1);

    auto out = torch::zeros_like(x);

    int block_size = 256;
    int num_blocks = (batch_size + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, out_features
    );

    return out;
}
"""

