__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

__global__ void gelu_softmax_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int batch_size, int out_features) {

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= batch_size) return;

    // Process each row entirely within this kernel
    const float* row_ptr = x + row * out_features;
    float* out_ptr = out + row * out_features;

    // First pass: find maximum in the row (after GELU)
    float max_val = -INFINITY;
    for (int j = 0; j < out_features; j++) {
        float val = gelu(row_ptr[j]);
        if (val > max_val) max_val = val;
    }

    // Second pass: compute softmax sum (combining GELU and softmax computation)
    float sum = 0.0f;
    for (int j = 0; j < out_features; j++) {
        sum += expf(gelu(row_ptr[j]) - max_val);
    }

    // Third pass: compute final softmax
    float inv_sum = 1.0f / (sum + 1e-8f);
    for (int j = 0; j < out_features; j++) {
        out_ptr[j] = expf(gelu(row_ptr[j]) - max_val) * inv_sum;
    }
}

