# Fused GroupNorm + Scale kernel
groupnorm_scale_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void groupnorm_scale_kernel(
    const float* input,
    float* output,
    const float* weight,  // gamma
    const float* bias,    // beta
    const float* scale,   // additional scale parameter
    int batch_size,
    int channels,
    int height,
    int width,
    int num_groups,
    float eps) {

    int C = channels;
    int G = num_groups;
    int C_per_G = C / G;
    int HxW = height * width;

    // Each thread block processes one (batch, group) pair
    int batch_idx = blockIdx.x;
    int group_idx = blockIdx.y;

    if (batch_idx >= batch_size || group_idx >= G) return;

    int C_start = group_idx * C_per_G;
    int C_end = C_start + C_per_G;
    int N = C_per_G * HxW;

    // Shared memory for mean and std
    __shared__ float mean_shared;
    __shared__ float inv_std_shared;

    // Compute sum and sum of squares using warp reduction
    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // Each thread processes multiple elements
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        // Convert linear index to channel and spatial
        int c_rel = i / HxW;
        int hw_idx = i % HxW;
        int c = C_start + c_rel;

        int idx = batch_idx * C * HxW + c * HxW + hw_idx;
        float val = input[idx];

        local_sum += val;
        local_sq_sum += val * val;
    }

    // Warp reduction using shfl_down
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset);
        local_sq_sum += __shfl_down(local_sq_sum, offset);
    }

    // Final reduction across warps - use first thread of each warp
    __shared__ float warp_sums[8];
    __shared__ float warp_sq_sums[8];

    int lane = threadIdx.x % 32;
    int warp_id = threadIdx.x / 32;

    if (lane == 0 && warp_id < 8) {
        warp_sums[warp_id] = local_sum;
        warp_sq_sums[warp_id] = local_sq_sum;
    }

    __syncthreads();

    if (threadIdx.x == 0) {
        float final_sum = 0.0f;
        float final_sq_sum = 0.0f;

        int num_warps = (blockDim.x + 31) / 32;
        for (int w = 0; w < num_warps && w < 8; w++) {
            final_sum += warp_sums[w];
            final_sq_sum += warp_sq_sums[w];
        }

        float mean = final_sum / N;
        float var = final_sq_sum / N - mean * mean;
        float std = sqrtf(fmaxf(var, 0.0f) + eps);

        mean_shared = mean;
        inv_std_shared = 1.0f / (std + 1e-8f);
    }

    __syncthreads();

    float mean = mean_shared;
    float inv_std = inv_std_shared;

    // Apply normalization, scaling
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        int c_rel = i / HxW;
        int hw_idx = i % HxW;
        int c = C_start + c_rel;

        int idx = batch_idx * C * HxW + c * HxW + hw_idx;
        float val = input[idx];
        float normalized = (val - mean) * inv_std;

        // Apply gamma, scale, and beta
        output[idx] = normalized * weight[c] * scale[c] + bias[c];
    }
}

torch::Tensor groupnorm_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale,
    int num_groups,
    float eps) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    const int threads = 256;
    dim3 blocks(batch_size, num_groups);

    groupnorm_scale_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        num_groups,
        eps);

    return output;
}
"""

# Fused MaxPool + Clamp kernel
maxpool_clamp_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void maxpool_clamp_kernel(
    const float* input,
    float* output,
    int out_height,
    int out_width,
    int in_height,
    int in_width,
    int in_stride_x,
    int out_stride_x,
    int num_channels,
    int kernel_size,
    int stride,
    float clamp_min,
    float clamp_max) {

    // Each thread block processes one (batch, channel, out_y) line
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;
    int out_y = blockIdx.x;

    if (out_y >= out_height) return;

    // Each thread processes multiple output x positions
    for (int out_x = threadIdx.x; out_x < out_width; out_x += blockDim.x) {
        // Calculate input window start
        int in_x_start = out_x * stride;
        int in_y_start = out_y * stride;

        // Find max value in the window
        float max_val = -1e20f;

        for (int ky = 0; ky < kernel_size; ky++) {
            for (int kx = 0; kx < kernel_size; kx++) {
                int in_x = in_x_start + kx;
                int in_y = in_y_start + ky;

                if (in_x >= 0 && in_x < in_width && in_y >= 0 && in_y < in_height) {
                    int idx = batch_idx * num_channels * in_height * in_width +
                              channel_idx * in_height * in_width +
                              in_y * in_width + in_x;
                    float val = input[idx];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }

        // Apply clamp
        max_val = fmaxf(fminf(max_val, clamp_max), clamp_min);

        // Write output
        int out_idx = batch_idx * num_channels * out_height * out_width +
                       channel_idx * out_height * out_width +
                       out_y * out_width + out_x;
        output[out_idx] = max_val;
    }
}

torch::Tensor maxpool_clamp_hip(
    torch::Tensor input,
    int kernel_size,
    float clamp_min,
    float clamp_max) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    int stride = kernel_size;  // Default stride equals kernel size

    int out_height = (in_height - kernel_size) / stride + 1;
    int out_width = (in_width - kernel_size) / stride + 1;

    auto output = torch::empty({batch_size, channels, out_height, out_width}, input.options());

    const int threads_x = 256;
    dim3 threads(threads_x);
    dim3 blocks(out_height, channels, batch_size);

    maxpool_clamp_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        out_height,
        out_width,
        in_height,
        in_width,
        in_width,
        out_width,
        channels,
        kernel_size,
        stride,
        clamp_min,
        clamp_max);

    return output;
}
"""

