# Fused Matmul + Dropout + Softmax kernel
fused_kernel_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    float scale,
    bool training
) {
    int out_row = blockIdx.y * blockDim.y + threadIdx.y;
    int out_col = blockIdx.x * blockDim.x + threadIdx.x;

    if (out_row >= batch_size || out_col >= out_features) return;

    float sum = 0.0f;

    for (int k = 0; k < in_features; ++k) {
        sum += x[out_row * in_features + k] * weight[out_col * in_features + k];
    }

    if (bias != nullptr) {
        sum += bias[out_col];
    }

    if (training) {
        unsigned int idx = (unsigned int)(out_row * out_features + out_col);
        unsigned int hash = idx * 0x9e3779b9;
        hash ^= hash >> 16;
        hash *= 0x85ebca6b;
        hash ^= hash >> 13;
        hash *= 0xc2b2ae35;
        hash ^= hash >> 16;
        float rand_val = (float)(hash & 0xFFFFFF) / (float)0x1000000;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum = sum * scale;
        }
    }

    output[out_row * out_features + out_col] = sum;
}

__global__ void softmax_find_max_kernel(
    const float* __restrict__ input,
    float* __restrict__ row_max,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float val = input[idx];

    atomicMax(&row_max[row], val);
}

__global__ void softmax_sum_exp_kernel(
    float* __restrict__ input,
    float* __restrict__ row_sum,
    const float* __restrict__ row_max,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float max_val = row_max[row];
    float exp_val = expf(fmaxf(input[idx] - max_val, -50.0f));
    input[idx] = exp_val;

    atomicAdd(&row_sum[row], exp_val);
}

__global__ void softmax_normalize_kernel(
    float* __restrict__ input,
    const float* __restrict__ row_sum,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float sum = row_sum[row];
    input[idx] = input[idx] / fmaxf(sum, 1e-10f);
}

torch::Tensor fused_matmul_dropout_softmax_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float dropout_p,
    bool training
) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());
    auto row_max = torch::full({batch_size}, -1e30f, x.options());
    auto row_sum = torch::zeros({batch_size}, x.options());
    float scale = 1.0f / (1.0f - dropout_p + 1e-6f);

    // Matmul+dropout
    dim3 blockDim(32, 8);
    dim3 gridDim((out_features + 31) / 32, (batch_size + 7) / 8);

    fused_matmul_dropout_softmax_kernel<<<gridDim, blockDim>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        dropout_p,
        scale,
        training
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        dim3 blockDim2(16, 16);
        dim3 gridDim2((out_features + 15) / 16, (batch_size + 15) / 16);
        fused_matmul_dropout_softmax_kernel<<<gridDim2, blockDim2>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.defined() ? bias.data_ptr<float>() : nullptr,
            output.data_ptr<float>(),
            batch_size,
            in_features,
            out_features,
            dropout_p,
            scale,
            training
        );
    }

    // Softmax
    int soft_block_x = 32;
    int soft_block_y = 32;
    dim3 s_thread(soft_block_x, soft_block_y);
    dim3 s_grid((out_features + soft_block_x - 1) / soft_block_x, (batch_size + soft_block_y - 1) / soft_block_y);

    softmax_find_max_kernel<<<s_grid, s_thread>>>(output.data_ptr<float>(), row_max.data_ptr<float>(), batch_size, out_features);
    softmax_sum_exp_kernel<<<s_grid, s_thread>>>(output.data_ptr<float>(), row_sum.data_ptr<float>(), row_max.data_ptr<float>(), batch_size, out_features);
    softmax_normalize_kernel<<<s_grid, s_thread>>>(output.data_ptr<float>(), row_sum.data_ptr<float>(), batch_size, out_features);

    return output;
}
"""

fused_module = load_inline(
    name="fused_matmul_dropout_softmax",
