matmul_pool_sum_scale_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE_K 128
#define BLOCK_ROWS 128

__global__ void matmul_pool_sum_scale_kernel(
    const float* input,  // (batch_size, in_features)
    const float* weight, // (out_features, in_features)
    const float* bias,   // (out_features)
    float* output,       // (batch_size,)
    int batch_size,
    int in_features,
    int out_features,
    float scale_factor
) {
    // Each block processes one sample (one row of the batch)
    int sample_idx = blockIdx.x;
    if (sample_idx >= batch_size) return;

    int num_pairs = out_features / 2;

    // Each thread computes multiple output pairs
 int pairs_per_thread = (num_pairs + BLOCK_ROWS - 1) / BLOCK_ROWS;
    int pair_start = threadIdx.x * pairs_per_thread;
    int pair_end = min(pair_start + pairs_per_thread, num_pairs);

    // Shared memory for input tile
    __shared__ float input_tile[TILE_SIZE_K];

    // Accumulator for this thread's sum
    float thread_sum = 0.0f;

    const float* input_row = input + sample_idx * in_features;

    // For each pair this thread is responsible for
    for (int pair = pair_start; pair < pair_end; pair++) {
        int out1 = 2 * pair;
        int out2 = 2 * pair + 1;

        const float* w1 = weight + out1 * in_features;
        const float* w2 = weight + out2 * in_features;

        // Accumulators for this pair
        float val1 = 0.0f;
        float val2 = 0.0f;

        // Tiled matmul
        for (int k_start = 0; k_start < in_features; k_start += TILE_SIZE_K) {
            int k_end = min(k_start + TILE_SIZE_K, in_features);
            int tile_len = k_end - k_start;

            // Load input tile coalesced
            int my_k = k_start + threadIdx.x;
            if (my_k < k_end) {
                input_tile[threadIdx.x] = input_row[my_k];
            }

            __syncthreads();

            // Compute dot product
            for (int k = 0; k < tile_len; k++) {
                float in_val = input_tile[k];
                val1 += in_val * w1[k_start + k];
                val2 += in_val * w2[k_start + k];
            }

            __syncthreads();
        }

        // Add bias
        val1 += bias[out1];
        val2 += bias[out2];

        // Max pool
        float pooled = fmaxf(val1, val2);
        thread_sum += pooled;
    }

    // Parallel reduction across threads
    __shared__ float partial_sums[BLOCK_ROWS];
    partial_sums[threadIdx.x] = thread_sum;

    __syncthreads();

    // Reduce
    for (int s = BLOCK_ROWS / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            partial_sums[threadIdx.x] += partial_sums[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Thread 0 writes the final scaled result
    if (threadIdx.x == 0) {
        output[sample_idx] = partial_sums[0] * scale_factor;
    }
}

torch::Tensor matmul_pool_sum_scale_hip(
    const torch::Tensor input,  // (batch_size, in_features)
    const torch::Tensor weight, // (out_features, in_features)
    const torch::Tensor bias,   // (out_features)
    float scale_factor
) {
    int batch_size = input.size(0);
    int in_features = input.size(1);
    int out_features = weight.size(0);

    // Output is (batch_size,)
    auto output = torch::empty({batch_size}, input.options());

    dim3 grid_dim(batch_size);
    dim3 block_dim(BLOCK_ROWS);

    matmul_pool_sum_scale_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        scale_factor
    );

    return output;
}
"""

