maxpool_clamp_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void maxpool_clamp_kernel(
    const float* input,
    float* output,
    int out_height,
    int out_width,
    int in_height,
    int in_width,
    int num_channels,
    int kernel_size,
    int stride,
    float clamp_min,
    float clamp_max) {

    // Global thread indices
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    int out_y = blockIdx.y * blockDim.y + threadIdx.y;

    // Bounds check
    if (out_x >= out_width || out_y >= out_height) return;

    // Process all channels and batches
    for (int batch_idx = 0; batch_idx < blockIdx.z; batch_idx++) {
        for (int channel_idx = 0; channel_idx < num_channels; channel_idx++) {
            int block_z = blockIdx.z;
            int b = block_z / num_channels;
            int c = block_z % num_channels;

            if (b >= batch_idx) break; // Simplification - handle one (batch, channel) per block

            // Re-calculate batch and channel from block z
            b = block_z / num_channels;
            c = block_z % num_channels;

            if (b >= batch_idx) continue;
        }
    }
}

// Simpler 2D kernel that processes one (batch, channel) per block
__global__ void maxpool_clamp_2d_kernel(
    const float* input,
    float* output,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    float clamp_min,
    float clamp_max) {

    // Each block processes one (batch, channel) pair
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;

    // Each thread processes one output position
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    int out_y = threadIdx.y; // Process one row per thread block

    if (out_x >= out_width) return;
    if (out_y >= out_height) return;

    // Calculate input window
    int in_x_start = out_x * stride;
    int in_y_start = out_y * stride;

    // Find max value in the kernel window
    float max_val = -1e38f;  // More negative initialization

    for (int ky = 0; ky < kernel_size; ky++) {
        int in_y = in_y_start + ky;
        if (in_y < 0 || in_y >= in_height) continue;

        for (int kx = 0; kx < kernel_size; kx++) {
            int in_x = in_x_start + kx;
            if (in_x < 0 || in_x >= in_width) continue;

            int idx = batch_idx * (int)blockDim.y * in_height * in_width +
                      channel_idx * in_height * in_width +
                      in_y * in_width + in_x;
            float val = input[idx];

            if (val > max_val) {
                max_val = val;
            }
        }
    }

    // Apply clamp
    if (max_val < clamp_min) max_val = clamp_min;
    if (max_val > clamp_max) max_val = clamp_max;

    // Calculate output index
    int out_idx = batch_idx * (int)blockDim.z * out_height * out_width +
                   channel_idx * out_height * out_width +
                   out_y * out_width + out_x;
    output[out_idx] = max_val;
}

torch::Tensor maxpool_clamp_hip(
    torch::Tensor input,
    int kernel_size,
    float clamp_min,
    float clamp_max) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    // PyTorch MaxPool2d default: stride = kernel_size
    int stride = kernel_size;

    // Calculate output dimensions
    int out_height = (in_height - kernel_size) / stride + 1;
    int out_width = (in_width - kernel_size) / stride + 1;

    auto output = torch::empty({batch_size, channels, out_height, out_width}, input.options());

    // Thread configuration
    const int block_x = 16;
    const int block_y = 16;
    dim3 threads(block_x, block_y);

    // Grid configuration - x for out_x, y is implicit in thread, z for (batch, channel)
    // Use y dimension for channels to avoid overflow
    dim3 blocks((out_width + block_x - 1) / block_x, channels, batch_size);

    maxpool_clamp_2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        in_height,
        in_width,
        out_height,
        out_width,
        kernel_size,
        stride,
        clamp_min,
        clamp_max);

    return output;
}
